import { cleanup, render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, expect, test, vi } from "vitest";

import type { EvaluationReader } from "./types";
import { EvaluationsPanel } from "./EvaluationsPanel";

afterEach(cleanup);

// The fixture was generated by running a real offline campaign (StubAgent +
// FakeGateway judge) through the real API endpoints, so every field below is
// the exact shape the backend serves.
import fixture from "./fixtures/evaluation.fixture.json";
import type {
  CampaignDetailDto,
  CampaignSummaryDto,
  RunDetailDto,
} from "./types";

const CAMPAIGNS = fixture.campaigns as unknown as CampaignSummaryDto[];
const DETAIL = fixture.campaignDetail as unknown as CampaignDetailDto;
const RUN = fixture.runDetail as unknown as RunDetailDto;

function reader(overrides: Partial<EvaluationReader> = {}): EvaluationReader {
  return {
    listCampaigns: vi.fn().mockResolvedValue(CAMPAIGNS),
    campaignDetail: vi.fn().mockResolvedValue(DETAIL),
    runDetail: vi.fn().mockResolvedValue(RUN),
    ...overrides,
  };
}

test("renders the campaign list with the headline metrics, newest first", async () => {
  render(<EvaluationsPanel reader={reader()} />);

  await waitFor(() => expect(screen.getByText("campaign-judged")).toBeTruthy());
  // The server orders newest first; both fixture campaigns render with identity,
  // time window, task count, strict rate, judge means and model name.
  expect(screen.getByText("campaign-plain")).toBeTruthy();
  expect(screen.getAllByText("100.0%").length).toBe(2);
  expect(screen.getAllByText("2 tasks").length).toBe(2);
  expect(screen.getByText("4.0 · 5.0 · 3.0")).toBeTruthy();
  expect(screen.getAllByText("claude-stub-model-2026").length).toBe(2);
  expect(screen.getAllByText(/2026-/).length).toBe(2);
});

test("shows the empty state when the results root has no campaigns", async () => {
  render(
    <EvaluationsPanel
      reader={reader({ listCampaigns: vi.fn().mockResolvedValue([]) })}
    />,
  );

  await waitFor(() =>
    expect(
      screen.getByText(
        "No evaluation campaigns found — run `coding-agent-eval run` to create one",
      ),
    ).toBeTruthy(),
  );
});

test("shows a loading state while the campaign index is read", () => {
  render(
    <EvaluationsPanel
      reader={reader({
        listCampaigns: vi.fn(() => new Promise<CampaignSummaryDto[]>(() => {})),
      })}
    />,
  );

  expect(screen.getByText("Loading evaluation campaigns…")).toBeTruthy();
});

test("shows an error state when the campaign index cannot be read", async () => {
  render(
    <EvaluationsPanel
      reader={reader({
        listCampaigns: vi.fn().mockRejectedValue(new Error("boom")),
      })}
    />,
  );

  await waitFor(() =>
    expect(
      screen.getByText("Unable to load evaluation campaigns."),
    ).toBeTruthy(),
  );
});

test("marks a corrupt campaign row instead of hiding it", async () => {
  const corrupt: CampaignSummaryDto = {
    ...CAMPAIGNS[0],
    campaign_id: null,
    corrupt: true,
    note: "unreadable runs.jsonl",
    task_count: 0,
  };
  render(
    <EvaluationsPanel
      reader={reader({ listCampaigns: vi.fn().mockResolvedValue([corrupt]) })}
    />,
  );

  await waitFor(() => expect(screen.getByText("corrupt")).toBeTruthy());
  expect(screen.getByText("unreadable runs.jsonl")).toBeTruthy();
});

test("opens a campaign and then one run, and returns along the same path", async () => {
  const user = userEvent.setup();
  const api = reader();
  render(<EvaluationsPanel reader={api} />);

  await waitFor(() => expect(screen.getByText("campaign-judged")).toBeTruthy());
  await user.click(screen.getByRole("button", { name: /campaign-judged/ }));

  await waitFor(() => expect(screen.getByText("demo-task")).toBeTruthy());
  expect(api.campaignDetail).toHaveBeenCalledWith("judged-campaign");

  await user.click(screen.getByRole("button", { name: /demo-task/ }));
  await waitFor(() =>
    expect(screen.getByRole("heading", { name: /demo-task/ })).toBeTruthy(),
  );
  expect(api.runDetail).toHaveBeenCalledWith("judged-campaign", "demo-task", 1);

  await user.click(screen.getByRole("button", { name: /Back to campaign/ }));
  await waitFor(() => expect(screen.getByText("second-task")).toBeTruthy());

  await user.click(screen.getByRole("button", { name: /Back to campaigns/ }));
  await waitFor(() => expect(screen.getByText("campaign-plain")).toBeTruthy());
});
